import sys

def solve():
    data = sys.stdin.read().split()
    if len(data) != 3:
        print("no")
        return
    try:
        a, b, c = map(int, data)
    except ValueError:
        print("no")
        return
    # Sides must be positive to form a triangle
    if a <= 0 or b <= 0 or c <= 0:
        print("no")
        return
    # Sort to identify the hypotenuse (largest side)
    x, y, z = sorted([a, b, c])
    if x * x + y * y == z * z:
        print("yes")
    else:
        print("no")

